import * as THREE from 'three';
import {ARCHERY_GEOMETRY as G} from './archery-layout.js';
import {ARCHERY_LIMITS} from './archery-model.js';
/** Authored lane surfaces also own the first-hit query; no score-only invisible target. */
export function buildArcheryView(parent){
 const machine=new THREE.Group();machine.name='schoolGym.archery';parent?.add(machine);const mats=new Map(),owned=new Set(),solids=[];
 const material=color=>{if(!mats.has(color))mats.set(color,new THREE.MeshStandardMaterial({color,roughness:.88,side:THREE.DoubleSide}));return mats.get(color);};
 const mesh=(g,c,name,at,host=machine)=>{owned.add(g);const m=new THREE.Mesh(g,material(c));m.name='schoolGym.archery.'+name;if(at)m.position.set(...at);m.castShadow=true;m.receiveShadow=true;host.add(m);return m;};
 const box=(w,h,d,c,name,at)=>mesh(new THREE.BoxGeometry(w,h,d),c,name,at);
 const mat=box(3.1,.012,6.7,'#d4d8bf','floor',[0,.006,2.3]);solids.push(mat);mat.userData.kind='floor';
 const backstop=box(3.1,2.1,.11,'#849e94','backstop',[0,1.062,G.backstopZ]);backstop.userData.kind='backstop';solids.push(backstop);
 for(const x of[-1.55,1.55]){const side=box(.08,1.6,4.3,'#bccdb9','side',[x,.812,3.45]);side.userData.kind='side';if(x<0){const clear=new THREE.MeshStandardMaterial({color:'#bccdb9',roughness:.6,transparent:true,opacity:.23,depthWrite:false,side:THREE.DoubleSide});mats.set('near-catch',clear);side.material=clear;}solids.push(side);}
 // One mesh with separately indexed real ring triangles, all on one target plane.
 const pos=[],norm=[],groups=[],colors=['#e3b953','#be735b','#7c9caa','#e4e2c9','#718e83'];let inner=0;
 for(const [ring,outer] of G.targetRadii.entries()){const start=pos.length/3;for(let i=0;i<48;i++){const a=i*Math.PI*2/48,b=(i+1)*Math.PI*2/48;for(const[r,t]of[[inner,a],[outer,b],[outer,a],[inner,a],[inner,b],[outer,b]]){pos.push(r*Math.cos(t),r*Math.sin(t),0);norm.push(0,0,-1);}}groups.push([start,pos.length/3-start,ring]);inner=outer;}
 const tg=new THREE.BufferGeometry();tg.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));tg.setAttribute('normal',new THREE.Float32BufferAttribute(norm,3));for(const g of groups)tg.addGroup(...g);owned.add(tg);const target=new THREE.Mesh(tg,colors.map(material));target.name='schoolGym.archery.target';target.position.set(0,G.targetY,G.targetZ);target.rotation.y=-Math.PI/4;target.userData.kind='target';machine.add(target);solids.push(target);
 const bow=new THREE.Group();bow.name='schoolGym.archery.bow';machine.add(bow);
 const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(0,-.49,.12),new THREE.Vector3(0,-.30,.01),new THREE.Vector3(0,0,0),new THREE.Vector3(0,.30,.01),new THREE.Vector3(0,.49,.12)]);
 const stave=mesh(new THREE.TubeGeometry(curve,18,.021,6,false),'#b58c5e','stave',null,bow),grip=mesh(new THREE.CylinderGeometry(G.gripRadius,G.gripRadius,G.gripHeight,16),'#687e70','grip',null,bow);
 const riser=['left','cross'].map(name=>mesh(new THREE.CylinderGeometry(.018,.018,1,8),'#b58c5e','offset-riser-'+name,null,bow));
 const strings=[-1,1].map(s=>mesh(new THREE.CylinderGeometry(.006,.006,1,5),'#ece7cc','string-'+s,null,bow));
 const nock=mesh(new THREE.SphereGeometry(G.nockRadius,16,12),'#e3b953','nock',null,bow);
 const arrow=new THREE.Group();arrow.name='schoolGym.archery.arrow';machine.add(arrow);const shaft=mesh(new THREE.CylinderGeometry(.010,.010,ARCHERY_LIMITS.arrowLength,6),'#966e43','shaft',null,arrow);shaft.rotation.x=Math.PI/2;shaft.position.z=-ARCHERY_LIMITS.arrowLength/2;const head=mesh(new THREE.ConeGeometry(.024,.07,6),'#6d8580','arrowhead',null,arrow);head.rotation.x=Math.PI/2;head.position.z=-.035;
 const v=new THREE.Vector3(),up=new THREE.Vector3(0,1,0),forward=new THREE.Vector3(0,0,1),q=new THREE.Quaternion(),ray=new THREE.Raycaster();let alive=true;
 function setBow(fit){if(!alive)return;if(!fit){bow.visible=false;arrow.visible=false;return;}bow.visible=true;bow.position.copy(fit.grip);bow.quaternion.copy(fit.quaternion);stave.position.copy(fit.stave).sub(fit.grip).applyQuaternion(q.copy(fit.quaternion).invert());const end=stave.position.clone(),elbow=new THREE.Vector3(0,end.y,end.z),start=new THREE.Vector3(0,0,0);for(const[i,ends]of[[start,elbow],[elbow,end]].entries()){const[a,b]=ends,d=b.clone().sub(a);riser[i].position.copy(a).add(b).multiplyScalar(.5);riser[i].scale.y=d.length();riser[i].quaternion.setFromUnitVectors(up,d.normalize());}nock.position.copy(fit.nock).sub(fit.grip).applyQuaternion(q.copy(fit.quaternion).invert());for(const[i,s]of[-1,1].entries()){const end=new THREE.Vector3(0,s*.49,.12).add(stave.position),start=nock.position,d=v.copy(end).sub(start);strings[i].position.copy(start).add(end).multiplyScalar(.5);strings[i].scale.set(1,d.length(),1);strings[i].quaternion.setFromUnitVectors(up,d.normalize());}if(!fit.arrow){arrow.visible=fit.draw>=0;v.copy(fit.direction);arrow.position.copy(fit.nock).addScaledVector(v,ARCHERY_LIMITS.arrowLength);arrow.quaternion.setFromUnitVectors(forward,v);}else{arrow.visible=true;arrow.position.set(fit.arrow.tip.x,fit.arrow.tip.y,fit.arrow.tip.z);v.set(fit.arrow.velocity.x,fit.arrow.velocity.y,fit.arrow.velocity.z).normalize();arrow.quaternion.setFromUnitVectors(forward,v);}machine.updateWorldMatrix(true,true);}
 function sweep(a,b){if(!alive)return null;machine.updateWorldMatrix(true,true);const start=machine.localToWorld(new THREE.Vector3(a.x,a.y,a.z)),end=machine.localToWorld(new THREE.Vector3(b.x,b.y,b.z)),d=end.sub(start),length=d.length();if(length<1e-12)return null;ray.set(start,d.normalize());ray.near=0;ray.far=length+1e-9;const h=ray.intersectObjects(solids,false).find(x=>x.object.visible);if(!h)return null;const p=machine.worldToLocal(h.point.clone()),kind=h.object.userData.kind;return{kind,score:kind==='target'?[10,8,6,4,2][h.face.materialIndex]:0,point:{x:p.x,y:p.y,z:p.z},object:h.object.name};}
 setBow(null);
 return{machine,mat,backstop,target,solids,bow,grip,nock,strings,stave,riser,arrow,setBow,sweep,dispose(){if(!alive)return;alive=false;machine.removeFromParent();for(const g of owned)g.dispose();for(const m of mats.values())m.dispose();}};
}
